import React, { useState, useRef, useEffect } from 'react';


function App() {
  const [userInput, setUserInput] = useState('');
  const [messages, setMessages] = useState([]);
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef(null);
  const [showModal, setShowModal] = useState(false);


  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const sendMessage = async () => {
    if (!userInput.trim()) return;

    const newMessages = [...messages, { type: 'user', text: userInput }];
    setMessages(newMessages);
    setUserInput('');
    setIsTyping(true);

    try {
      const response = await fetch('https://hook.eu2.make.com/fci7oybacyp9pytg3hg1irh8dtlzq5b9', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: userInput, history: messages }),
      });

      const data = await response.json();
      setMessages([...newMessages, { type: 'bot', text: data.reply }]);
    } catch (error) {
      setMessages([...newMessages, { type: 'bot', text: 'Feil ved henting av svar.' }]);
    }

    setIsTyping(false);
  };

  return (
    <div className="max-w-2xl mx-auto mt-10 p-4 border border-gray-300 rounded-xl shadow-md bg-white h-[90vh] flex flex-col">
      <h1 className="text-2xl font-bold text-center mb-6 mt-3">🤖 AI-Chatbot for Nor Klinikken Madla</h1>
      <div className="flex-1 overflow-y-auto px-2 space-y-3">
        {messages.map((msg, index) => (
          <div
            key={index}
            className={ "max-w-[80%] p-3 rounded-lg whitespace-pre-wrap break-words " + (msg.type === 'user' ? 'border black-400 bg-blue-600 text-white self-end ml-auto shadow-sm' : 'border black-400 bg-gray-100 text-gray-900 self-start mr-auto shadow-sm') }          >
            {msg.text}
          </div>
        ))}

        {isTyping && (
          <div className="max-w-[80%] p-3 rounded-lg bg-gray-100 text-gray-1200 self-start mr-auto border shadow-sm">
            <span className="typing-dots">Skriver</span>
          </div>
        )}



        <div ref={messagesEndRef} />
      </div>
      <div className="mt-4 flex gap-2">
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
          placeholder="Skriv et spørsmål..."
          className="flex-1 p-3 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-400"
        />
        <button
          onClick={sendMessage}
          className="bg-blue-600 text-white px-4 py-2 rounded-md hover:bg-blue-700 transition"
        >
          Send
        </button>
      </div>

      {/* Info-knapp og modal */}
      <div className="mt-2 text-center text-sm text-gray-500">
        <button onClick={() => setShowModal(true)} className="text-black-600 text-xs">
          <a href="https://digisaga.no">Digisaga.no   |    </a>ℹ️ Personvern
        </button>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-40 flex justify-center items-center z-50">
          <div className="bg-white p-6 rounded-lg shadow-lg max-w-xs text-sm relative">
            <button
              onClick={() => setShowModal(false)}
              className="absolute top-2 right-2 text-gray-400 hover:text-gray-600 text-lg"
            >
              &times;
            </button>
            <p className="mb-2">
              Denne chatten lagrer ikke sensitive personopplysninger og brukes kun for å svare på generelle spørsmål. Informasjonen slettes når du forlater siden.
            </p>
            <p className="text-xs text-gray-400">
              🤖 Chatboten er utviklet av <a href="https://digisaga.no" className="underline">Digisaga.no</a>.
            </p>
          </div>
        </div>
      )}




    </div>
  );
}

export default App;
